"""Log diagnostic helpers built on ORX failure classification."""

from orx.adapters.base import error_kind_from_text


def classify_log(text, timed_out=False):
    """Classify a log text using ORX, overriding to 'timeout' when reasoning timed out."""
    if timed_out:
        return "timeout"
    return error_kind_from_text(text)
